-- Conference Tracker: conference list (169 records, updated 12 November 2026).
-- Research areas use ANZSRC 2020 codes: for_groups (4-digit groups) and for_fields (6-digit fields).
-- Run after 01_schema.sql. Safe to run again: records are updated in place, never deleted,
-- so everyone's saved statuses stay linked.

on conflict (id) do update set series=excluded.series, name=excluded.name, host=excluded.host, host_score=excluded.host_score, host_note=excluded.host_note, region=excluded.region, continent=excluded.continent, country=excluded.country, city=excluded.city, mode=excluded.mode, start_date=excluded.start_date, end_date=excluded.end_date, date_text=excluded.date_text, deadline=excluded.deadline, deadline_note=excluded.deadline_note, areas=excluded.areas, for_groups=excluded.for_groups, for_fields=excluded.for_fields, doctoral=excluded.doctoral, journals=excluded.journals, url=excluded.url, note=excluded.note, override=excluded.override, placeholder=excluded.placeholder;

-- Placeholders replaced by real conferences: archived (hidden), never deleted.
update public.conferences set archived = true where id in ('tbc1', 'tbc5', 'tbc9');
